// components/LightsIntro.jsx
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const LightsIntro = ({ onComplete }) => {
  const [phase, setPhase] = useState('dark'); // 'dark' | 'burst' | 'products'
  const navigate = useNavigate();

  const ignite = () => {
    setPhase('burst');
    setTimeout(() => setPhase('products'), 1100);
  };

  if (phase === 'products') return null; // hand off to normal Products page

  return (
    <div style={{
      position: 'fixed', inset: 0, background: '#000',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      zIndex: 9999, flexDirection: 'column', textAlign: 'center'
    }}>
      {phase === 'dark' && (
        <>
          <p style={{ color: '#444', letterSpacing: 6, fontSize: 12, marginBottom: 20 }}>
            WAIT . WAIT . WAIT
          </p>
          <h1 style={{ color: '#fff', fontSize: 'clamp(24px,5vw,42px)', fontWeight: 900, lineHeight: 1.2, marginBottom: 12 }}>
            Want to buy <span style={{ color: '#ffdd44' }}>light</span><br/>
            <span style={{ color: '#555' }}>to remove the</span><br/>
            darkness around you?
          </h1>
          <button onClick={ignite} style={{
            marginTop: 32, border: '1px solid #ffdd44', background: 'transparent',
            color: '#ffdd44', padding: '14px 36px', fontSize: 13,
            letterSpacing: 3, fontWeight: 700, cursor: 'pointer'
          }}>
            TURN ON THE LIGHTS →
          </button>
        </>
      )}
      {phase === 'burst' && (
        <div style={{ fontSize: 80, animation: 'spin 0.5s ease' }}>💥</div>
      )}
    </div>
  );
};

export default LightsIntro;
